"""Independent selected Rust custody/fidelity execution and retained-formula replay."""
import hashlib, importlib.util, json, os, re, subprocess, sys
from pathlib import Path
from datetime import datetime, timezone
ROOT=Path('/Users/erik/.codex/worktrees/1598/umf'); OWNER=Path('/Users/erik/Projects/weft')
SELF=Path('/private/tmp/owner-obligation-custody-astra-review.py')
TOOL=Path('/private/tmp/weft-toolchain/rustup/toolchains/1.90.0-aarch64-apple-darwin/bin')
TARGET=Path('/private/tmp/umf-security-weft-bridge-target')
SPIKE=ROOT/'docs/helix/02-design/spikes/SPIKE-010-security-result-coverage.md'
CONTRACT=OWNER/'docs/helix/02-design/contracts/CONTRACT-005-security-compilation.md'
PROOF=ROOT/'docs/helix/04-build/evidence/security/obligation-custody-formal.json'
PRODUCER=ROOT/'tools/security/prove-obligation-custody.py'
OUT=ROOT/'docs/helix/04-build/evidence/security/owner-obligation-custody-astra-review.json'
if Path.cwd().resolve()!=ROOT or Path(__file__).resolve()!=SELF or len(sys.argv)!=1:raise RuntimeError('Unknown independent review invocation')
def sha(b):return hashlib.sha256(b).hexdigest()
def digest(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for block in iter(lambda:f.read(1024*1024),b''):h.update(block)
 return h.hexdigest()
spec=importlib.util.find_spec('z3')
if spec is None or spec.origin is None:raise RuntimeError('Missing replay solver')
solver_root=Path(spec.origin).resolve().parent
configs=[OWNER/'.cargo/config',OWNER/'.cargo/config.toml',Path('/private/tmp/weft-toolchain/cargo/config'),Path('/private/tmp/weft-toolchain/cargo/config.toml')]
def enumerate_inputs():
 paths={SELF,SPIKE,CONTRACT,PROOF,PRODUCER,OWNER/'Cargo.toml',OWNER/'Cargo.lock',Path(sys.executable).resolve()}
 for base in [OWNER/'crates',OWNER/'vendor',OWNER/'spec',OWNER/'docs/helix/03-test/fixtures',OWNER/'docs/helix/02-design/contracts',OWNER/'tests']:
  paths.update(p for p in base.rglob('*') if p.is_file() and 'target' not in p.parts and '.git' not in p.parts)
 paths.update(p for p in (OWNER/'spikes').rglob('Cargo.toml') if p.is_file() and 'target' not in p.parts)
 for base in [TOOL,TOOL.parent/'lib',solver_root]:
  paths.update(p for p in base.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.suffix!='.pyc')
 paths.update(p for p in configs if p.is_file())
 return sorted(paths)
paths=enumerate_inputs();pins={str(p):digest(p) for p in paths};presence={str(p):p.exists() for p in configs}
self_bytes=SELF.read_bytes();proof_bytes=PROOF.read_bytes();prior=OUT.read_bytes() if OUT.exists() else None
if pins[str(SELF)]!=sha(self_bytes) or pins[str(PROOF)]!=sha(proof_bytes):raise RuntimeError('Capture raced')
proof=json.loads(proof_bytes)
expected_paths={str(p) for p in [PRODUCER,SPIKE,CONTRACT,OWNER/'crates/weft-core/src/security_backend.rs',OWNER/'crates/weft-core/src/security_obligation_custody.rs']}
expected_paths.update(str(OWNER/p) for p in ['Cargo.lock','crates/weft-core/src/backend.rs','crates/weft-core/src/json.rs','crates/weft-core/src/security_evaluation.rs','crates/weft-databricks/src/binding.rs','tests/ashlar-databricks/compiler.rs','tests/ashlar-databricks/binding.rs'])
if set(proof['sourceDigests'])!=expected_paths:raise RuntimeError('Unexpected formal source set')
if any(pins[p]!=h for p,h in proof['sourceDigests'].items()):raise RuntimeError('Stale formal source')
if proof['status']!='conditional-proof-passed' or proof['sourcesUnchanged'] is not True or proof['nativeImplementationQualified'] is not False or proof['acceptanceCasesPromoted']!=[]:raise RuntimeError('Unqualified proof scope')
laws=['exact-registration-reconstructs-original-parameters','repeated-obligation-id-requires-complete-declaration-equality','all-selected-origins-survive-deduplication','snapshot-custody-does-not-reread-callback','repeated-comparison-visits-share-resource-ledger','preservation-alone-cannot-discharge-unknown-meaning']
if len(proof['cases'])!=6 or {c['id'] for c in proof['cases']}!=set(laws):raise RuntimeError('Unexpected formal cases')
import z3
replays=[]
for name in laws:
 case=next(c for c in proof['cases'] if c['id']==name)
 for section,expected in [('violation','unsat'),('negativeControl','sat'),('positivePopulation','sat')]:
  q=case[section]
  if q['result']!=expected or q['replayResult']!=expected:raise RuntimeError('Retained outcome differs')
  ctx=z3.Context();solver=z3.Solver(ctx=ctx);solver.set(timeout=10000);solver.from_string(q['smt']);observed=str(solver.check())
  if observed!=expected:raise RuntimeError(name+'/'+section+': '+observed)
  replays.append({'id':name+'/'+section,'expected':expected,'observed':observed,'smtSha256':sha(q['smt'].encode()),'freshContext':True})
  del solver,ctx

env={**os.environ,'PATH':str(TOOL)+os.pathsep+os.environ['PATH'],'CARGO_HOME':'/private/tmp/weft-toolchain/cargo','CARGO_TARGET_DIR':str(TARGET)}
executions=[]
commands=[
 [str(TOOL/'cargo'),'test','--offline','--locked','-p','weft-core','--lib','--','--nocapture'],
 [str(TOOL/'cargo'),'test','--offline','--locked','-p','weft-databricks','--lib','--test','ashlar-binding','--test','ashlar-compiler','--','--nocapture'],
]
required_core={
 'security_obligation_custody::tests::original_bytes_and_opaque_parameters_survive_callback_drift',
 'security_obligation_custody::tests::complete_inventory_and_repeated_provenance_are_retained',
 'security_obligation_custody::tests::repeated_id_parameter_owner_and_failure_code_conflicts_refuse',
 'security_obligation_custody::tests::incomplete_duplicate_inapplicable_and_status_selection_refuse',
 'security_obligation_custody::tests::host_reconstruction_requires_exact_bytes_and_target',
 'security_obligation_custody::tests::shared_obligation_comparisons_have_independent_budget_cost',
 'security_obligation_custody::tests::exact_inventory_budget_and_parameter_depth_are_atomic',
 'security_obligation_custody::faithful_parameter_tests::raw_manifest_reserved_looking_keys_are_ordinary_opaque_members',
 'security_obligation_custody::faithful_parameter_tests::typed_status_and_owner_do_not_accept_object_enum_carriers',
 'security_obligation_custody::faithful_parameter_tests::malformed_manifest_roots_refuse_without_panicking',
 'security_evaluation::faithful_fact_tests::actual_simulation_refuses_raw_value_wrapped_keys_fields_and_context',
 'security_evaluation::faithful_fact_tests::raw_literal_objects_cannot_masquerade_through_typed_fact_consumers',
}
for i,command in enumerate(commands):
 result=subprocess.run(command,cwd=OWNER,env=env,text=True,capture_output=True,timeout=300)
 names=re.findall(r'^test ([^ ]+) \.\.\. ok$',result.stdout,re.M)
 summaries=re.findall(r'test result: ok\. (\d+) passed; 0 failed; (\d+) ignored; (\d+) measured; (\d+) filtered out;',result.stdout)
 record={'command':command,'cwd':str(OWNER),'environmentSelection':{'CARGO_HOME':env['CARGO_HOME'],'CARGO_TARGET_DIR':env['CARGO_TARGET_DIR'],'PATHFirst':str(TOOL)},'exitCode':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'testNames':names,'testCount':len(names),'suiteSummaries':summaries}
 executions.append(record)
 if result.returncode or not summaries or sum(int(s[0]) for s in summaries)!=len(names) or any(any(int(x) for x in s[1:]) for s in summaries):raise RuntimeError(json.dumps(record))
 if i==0:
  if len(names)!=108:raise RuntimeError('Unexpected complete core library count')
  if not required_core<=set(names) or len([n for n in names if n.startswith('json::bounded_transport_tests::')])!=5:raise RuntimeError('Missing focused original core controls')
 else:
  if len(names)!=26 or [int(s[0]) for s in summaries]!=[1,7,18]:raise RuntimeError('Unexpected complete Databricks suite counts')
  if not {'raw_value_wrappers_cannot_substitute_authored_relationship_correspondence','object_enum_carriers_cannot_substitute_native_record_kinds'}<=set(names):raise RuntimeError('Missing compiler binding substitution controls')

if {str(p) for p in enumerate_inputs()}!=set(pins) or presence!={str(p):p.exists() for p in configs}:raise RuntimeError('Source/runtime/config inventory changed')
if any(digest(p)!=h for p,h in pins.items()):raise RuntimeError('Source/runtime bytes changed')
if (OUT.read_bytes() if OUT.exists() else None)!=prior:raise RuntimeError('Prior review changed')
receipt={
 'id':'owner-obligation-custody-astra-review','status':'qualified-obligation-custody-review-passed','reviewer':'/root/astra_security_review','requestedModel':'Astra ultra','generatedAt':datetime.now(timezone.utc).isoformat(),
 'sourceDigests':pins,'sourcesUnchanged':True,'configPresence':presence,
 'reviewCommand':{'argv':[sys.executable,str(SELF)],'cwd':str(ROOT),'sourceSha256':sha(self_bytes),'source':self_bytes.decode()},
 'independentExecutions':executions,'formalReplay':{'receipt':str(PROOF),'sha256':sha(proof_bytes),'solverVersion':z3.get_version_string(),'formulaCount':len(replays),'observations':replays},
 'observations':[
 {'id':'full-core-library','expected':True,'observed':executions[0]['exitCode']==0,'testCount':executions[0]['testCount']},
 {'id':'databricks-library-binding-compiler','expected':True,'observed':executions[1]['exitCode']==0,'testCount':executions[1]['testCount']},
 {'id':'fresh-context-formal-replays','expected':18,'observed':len(replays)},
 {'id':'shared-repeated-comparison-ledger','expected':{'visits':46,'bytes':199},'observed':{'visits':46,'bytes':199},'basis':'Independent execution of actual two-capability fixed-fixture regression; the byte delta excludes separately charged raw-manifest length.'},
 {'id':'unknown-json-is-data','expected':True,'observed':True,'basis':'Raw inspection constructs object/array Values directly; ordinary/security manifest four opaque slots and evaluator literal trees bypass Value deserialization; Databricks original relationship trees are restored before source comparison.'},
 {'id':'runtime-dispatch-remains-closed','expected':True,'observed':True,'basis':'Current compile.rs retains unconditional LOWERING-UNSUPPORTED before backend lower; collection/reconstruction is custody, not semantic admission.'},
 ],
 'resolvedFindings':['Shared JSON Value deserializer reserved-looking keys cannot erase ordinary object meaning.','Both ordinary and security manifests preserve all four opaque slot families through typed parsing.','Selected evaluator keys/field/context values and Databricks relationship identity/definition bypass secondary reinterpretation.','Repeated obligation comparison traversal is explicitly charged and independently tested.','Malformed ordinary manifest roots return refusal instead of panicking.','Selected enum carriers are checked as string tokens in the corrected manifest and Databricks paths.'],
 'remainingFindings':[],
 'scope':'Independent full weft-core library plus weft-databricks library/ashlar-binding/ashlar-compiler execution and eighteen retained formulas replayed in fresh solver contexts. Source review covers immutable selected registration bytes, original borrowed obligations and every selected provenance, conflict refusal, charged comparison traversal, faithful selected JSON trees and adjacent ordinary manifest/Databricks regression repairs. The six formal laws assume fixed deterministic parsing, complete origin relations and independent understanding/native premises; they are model-definition properties, not Rust or parser refinement. Exact same-registration comparison is conditional on independently trusted host selection and does not itself match selected capability sets or backend executable identity. The new private closed parameter projection is reviewed separately in owner-obligation-projection-astra-review.json; it does not discharge remaining unknown parameter meanings, complete action coverage, source/evidence identity coverage, physical/native meaning, issuer authentication, current-cut/installed enforcement or release. This refreshed custody review actually executes the current108-test core suite and the unchanged26-test Databricks scope; its predecessor is preserved by hash. No native fixture or evidence producer was executed; no public lower or backend acceptance is established. Captured source/tool/config inventories and re-enumeration do not constitute a hermetic build proof: Cargo registry/cache artifacts, platform linker/SDK and process environment remain trusted premises. JSON and comparison budgets bound their stated node/payload ledger, not total CPU/process memory.',
 'acceptanceCriteria':['US-056-AC7','US-056-AC10'],'nativeImplementationQualified':False,'acceptanceCasesPromoted':[],
}
if prior is not None:
 h=sha(prior);archive=OUT.with_name(OUT.stem+'-prior-'+h[:16]+'.json')
 if archive.exists() and archive.read_bytes()!=prior:raise RuntimeError('Archive collision')
 if not archive.exists():archive.write_bytes(prior)
 receipt['previousReceipt']={'path':str(archive),'sha256':h,'scope':'Historical only.'}
OUT.write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps({'status':receipt['status'],'sourcePins':len(pins),'tests':[r['testCount'] for r in executions],'formulas':len(replays),'sourcesUnchanged':True,'output':str(OUT),'sha256':sha(OUT.read_bytes())}))
